class Solution {
  public int countRangeSum(int[] nums, int lower, int upper) {
    long[] prefix = new long[nums.length + 1];
    for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    return sortCount(prefix, new long[prefix.length], 0, prefix.length, lower, upper);
  }

  // merge sort over prefix sums; while merging, count pairs (i < j) with lower <= p[j] - p[i] <= upper
  private int sortCount(long[] p, long[] tmp, int lo, int hi, int lower, int upper) {
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) >>> 1;
    int count = sortCount(p, tmp, lo, mid, lower, upper) + sortCount(p, tmp, mid, hi, lower, upper);
    int a = mid, b = mid;
    for (int i = lo; i < mid; i++) {
      while (a < hi && p[a] - p[i] < lower) a++;
      while (b < hi && p[b] - p[i] <= upper) b++;
      count += b - a;
    }
    int i = lo, j = mid, k = lo;
    while (i < mid || j < hi) tmp[k++] = j == hi || (i < mid && p[i] <= p[j]) ? p[i++] : p[j++];
    System.arraycopy(tmp, lo, p, lo, hi - lo);
    return count;
  }
}
